     for (const blog of blogList) {
       const data = fs.readFileSync(blog, 'utf-8');
-      const includeChinese = /[\u4E00-\u9FA5]/.test(data);
+      const contentWithoutCodeBlocks = data.replace(/```[\s\S]*?```/g, '');
