+      absolute.host !== base.host ||
+      absolute.username !== "" ||
+      absolute.password !== ""
+    ) {
+      throw new ERR_INVALID_URL(path);
+    }
+    return absolute.href;
+  }
+
+  try {
+    return new URL(base.origin + path).href;
+  } catch {
+    const portSuffix = +port === 80 ? "" : `:${port}`;
+    return `http://${authorityHost}${portSuffix}${path}`;
