diff --git a/integration/animations/src/app/home.component.ts b/integration/animations/src/app/home.component.ts
--- a/integration/animations/src/app/home.component.ts
+++ b/integration/animations/src/app/home.component.ts
@@ -0,0 +1,42 @@
+import {Component} from '@angular/core';
+import {
+  CdkDragDrop,
+  CdkDropList,
+  CdkDrag,
+  CdkDragPlaceholder,
+  moveItemInArray,
+} from '@angular/cdk/drag-drop';
+
+@Component({
+  selector: 'app-home',
+  imports: [CdkDropList, CdkDrag, CdkDragPlaceholder],
+  templateUrl: './app.component.html',
+  styleUrl: './app.component.css',
+})
+export class HomeComponent {
+  movies = [
+    'Episode I - The Phantom Menace',
+    'Episode II - Attack of the Clones',
+    'Episode III - Revenge of the Sith',
+  ];
+
+  showFallback = true;
+
+  drop(event: CdkDragDrop<string[]>) {
+    moveItemInArray(this.movies, event.previousIndex, event.currentIndex);
+  }
+
+  hideAndIntercept() {
+    const el = document.querySelector('.fallback-el');
+    if (el) {
+      el.addEventListener(
+        'animationend',
+        (e) => {
+          e.stopImmediatePropagation();
+        },
+        true,
+      );
+    }
+    this.showFallback = false;
+  }
+}

