       }
     }

-    return false;
+    return foundCharacters;
+  }
+
+  private static _countNonSpaceCharacters(s: string): number {
+    let count: number = 0;
+    const length: number = s.length;
+    let i: number = 0;
+    while (i < length) {
+      switch (s.charCodeAt(i)) {
+        case 32:  // space
+        case 9:   // tab
+        case 13:  // CR
+        case 10:  // LF
