@@ -0,0 +1,45 @@
+// @strict: true
+// @noEmit: true
+
+function test1(a: number | string) {
+  if (typeof a === "number") {
+    const fn = (arg: typeof a) => true;
+    return fn;
+  }
+  return;
+}
+
+test1(0)?.(100);
+test1(0)?.("");
+
+function test2(a: number | string) {
+  if (typeof a === "number") {
+    const fn: { (arg: typeof a): boolean; } = () => true;
+    return fn;
+  }
+  return;
+}
+
+test2(0)?.(100);
+test2(0)?.("");
+
+function test3(a: number | string) {
+  if (typeof a === "number") {
+    return (arg: typeof a) => {};
+  }
+  throw new Error("");
+}
+
+test3(1)(100);
+test3(1)("");
+
+function test4(a: number | string) {
+  let fn = (arg: typeof a) => {};
+  if (Math.random() && typeof a === "number") {
+    return fn;
+  }
+  throw new Error("");
+}
+
+test4(1)?.(100);
+test4(1)?.("");

